INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'Attributes', N'خصوصیات محصول', N'خصوصیاتی مثل سایز، رنگ یا جنس را تعریف کنید تا در صفحه محصول نمایش داده شوند و مشتری بتواند با آن‌ها فیلتر کند.', NULL, N'Attributes');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'Categories', N'گروه‌های محصول', N'کالاها را در گروه‌ها و زیرگروه‌ها مرتب کنید تا مشتری راحت‌تر پیدایشان کند.', NULL, N'Categories');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'Collections', N'برچسب‌های ویژه', N'با برچسب‌ها کالاهایی مثل «ویژه روز دختر» یا «حراج یلدا» را جدا کنید و در صفحه اول یک ردیف مخصوص برایشان بسازید.', NULL, N'Collections');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'Customers', N'مشتریان', N'فهرست مشتریانی که در فروشگاه شما ثبت‌نام کرده‌اند.', NULL, N'Customers');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'EditAttribute', N'تعریف خصوصیت', N'یک خصوصیت کالا مثل سایز یا رنگ را تعریف کنید.', NULL, N'EditAttribute');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'EditCategory', N'ساخت و ویرایش گروه', N'یک گروه کالا بسازید یا اطلاعات آن را تغییر دهید.', NULL, N'EditCategory');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'EditCollection', N'ساخت برچسب ویژه', N'در این آموزش یک برچسب مثل «ویژه روز دختر» می‌سازید و کالاهایش را انتخاب می‌کنید.', NULL, N'EditCollection');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'EditMenu', N'افزودن آیتم منو', N'یک لینک به منوی سایت اضافه کنید یا آن را ویرایش کنید.', NULL, N'EditMenu');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'EditPage', N'ساخت و ویرایش صفحه', N'محتوای یک صفحه سایت را با ویرایشگر دیداری بنویسید.', NULL, N'EditPage');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'EditProduct', N'افزودن و ویرایش محصول', N'اطلاعات یک کالا را از عنوان و قیمت تا عکس‌ها، برچسب‌ها و خصوصیات وارد کنید.', NULL, N'EditProduct');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'Gallery', N'گالری تصاویر', N'تصاویر را یک‌بار آپلود کنید و آدرسشان را در صفحات و بنرهای سایت استفاده کنید.', NULL, N'Gallery');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'Index', N'داشبورد فروشگاه', N'در این آموزش با داشبورد پنل مدیریت و راه رسیدن به بخش‌های مختلف آشنا می‌شوید.', NULL, N'');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'Menus', N'منوهای سایت', N'منوی بالای سایت و لینک‌های فوتر را از اینجا مدیریت کنید.', NULL, N'Menus');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'Orders', N'سفارش‌ها', N'سفارش‌های مشتریان را ببینید و وضعیت هر سفارش را به‌روز کنید.', NULL, N'Orders');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'PageLayout', N'چیدمان صفحات', N'انتخاب کنید صفحه اول و صفحه محصول سایت شما چه بخش‌هایی داشته باشند و به چه ترتیبی نمایش داده شوند.', NULL, N'PageLayout');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'Pages', N'صفحات سایت', N'صفحه‌هایی مثل «درباره ما»، «شرایط فروش» یا «سؤالات متداول» بسازید.', NULL, N'Pages');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'Products', N'مدیریت محصولات', N'در این آموزش می‌بینید چطور محصولات فروشگاه را ببینید، اضافه کنید، ویرایش و حذف کنید.', NULL, N'Products');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'Reviews', N'نظرات مشتریان', N'نظراتی که مشتریان برای کالاها می‌نویسند را بررسی، تأیید یا حذف کنید.', NULL, N'Reviews');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'Settings', N'اطلاعات و ظاهر فروشگاه', N'همه تنظیمات اصلی فروشگاه در این صفحه است: نام و لوگو، قالب و رنگ، شبکه‌های اجتماعی، دامنه و درگاه پرداخت.', NULL, N'Settings');
INSERT INTO [dbo].[Tutorials] ([Page], [Title], [Intro], [Outro], [Path]) VALUES (N'Setup', N'راه‌اندازی سریع فروشگاه', N'در ۵ قدم کوتاه فروشگاه را آماده فروش کنید. هر قدم را می‌توانید رد کنید و بعداً کامل کنید.', NULL, N'Setup');
