INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Attributes', 0, N'.admin-main .btn-store', NULL, N'خصوصیت جدید', N'یک خصوصیت مثل «سایز» بسازید و مشخص کنید متنی، عددی یا انتخابی باشد.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Attributes', 1, N'.admin-main .panel-card .table', NULL, N'فهرست خصوصیات', N'ستون «گروه‌های مرتبط» نشان می‌دهد هر خصوصیت برای کالاهای کدام گروه پرسیده می‌شود. ستون «فیلتر» یعنی در فروشگاه قابل فیلتر است.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Attributes', 2, N'.admin-main .table a[href*="EditAttribute"]', NULL, N'ویرایش', N'گزینه‌ها، نوع یا گروه‌های مرتبط یک خصوصیت را تغییر دهید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Categories', 0, N'.admin-main .btn-store', NULL, N'گروه جدید', N'یک گروه اصلی مثل «زنانه» یا یک زیرگروه مثل «مانتو» بسازید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Categories', 1, N'.admin-main .panel-card .table', NULL, N'درخت گروه‌ها', N'زیرگروه‌ها با تورفتگی زیر گروه والد نمایش داده می‌شوند. ستون «ترتیب» جای هر گروه را در منو و فیلترها مشخص می‌کند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Categories', 2, N'.admin-main .table a[href*="EditCategory"]', NULL, N'ویرایش گروه', N'عنوان، گروه والد، ترتیب یا توضیحات گروه را تغییر دهید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Categories', 3, N'.admin-main .table .is-delete', NULL, N'حذف گروه', N'با حذف یک گروه، زیرگروه‌هایش هم حذف می‌شوند؛ پیش از حذف، کالاهایش را به گروه دیگری ببرید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Collections', 0, N'.admin-main .btn-store', NULL, N'برچسب جدید', N'یک برچسب بسازید، کالاهایش را تیک بزنید و انتخاب کنید که در صفحه اول نمایش داده شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Collections', 1, N'.admin-main .panel-card .table, .admin-empty', NULL, N'فهرست برچسب‌ها', N'تعداد کالاهای هر برچسب و اینکه در صفحه اول نمایش داده می‌شود یا نه را اینجا ببینید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Collections', 2, N'.admin-main .table a[target=_blank]', NULL, N'مشاهده در سایت', N'هر برچسب یک صفحه جدا در فروشگاه دارد که فقط کالاهای همان برچسب را نشان می‌دهد. می‌توانید لینکش را در بنرها یا شبکه‌های اجتماعی بگذارید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Collections', 3, N'.admin-main > p.small', NULL, N'جای ردیف در صفحه اول', N'برای جابه‌جا کردن ردیف برچسب در صفحه اول یا تغییر عنوانش به «چیدمان صفحات» بروید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Customers', 0, N'.admin-main .panel-card .table', NULL, N'فهرست مشتریان', N'نام، موبایل، ایمیل و تاریخ عضویت هر مشتری. مشتریان هنگام ثبت سفارش یا از صفحه «حساب» در سایت ثبت‌نام می‌کنند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Customers', 1, N'.admin-side a[href$="/Orders"]', NULL, N'سفارش‌های مشتریان', N'برای دیدن خریدهای مشتریان و تغییر وضعیت سفارش‌ها به بخش «سفارش‌ها» بروید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditAttribute', 0, NULL, N'Name', N'نام خصوصیت', N'مثلاً «سایز»، «رنگ» یا «جنس».');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditAttribute', 1, NULL, N'InputType', N'نوع', N'«انتخابی» برای مقادیر ثابت مثل سایز، «عدد» برای مقادیری مثل وزن و «متن» برای بقیه.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditAttribute', 2, NULL, N'Options', N'گزینه‌ها', N'برای نوع انتخابی، گزینه‌ها را با کاما جدا کنید؛ مثلاً S,M,L,XL.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditAttribute', 3, NULL, N'IsFilterable', N'قابل فیلتر', N'با این تیک، مشتری در صفحه محصولات می‌تواند کالاها را بر اساس این خصوصیت فیلتر کند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditAttribute', 4, NULL, N'categoryIds', N'گروه‌های مرتبط', N'خصوصیت فقط برای کالاهای گروه‌های انتخاب‌شده پرسیده می‌شود. اگر هیچ گروهی انتخاب نشود، برای همه کالاهاست.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditAttribute', 5, N'.admin-main form .btn-store[type=submit]', NULL, N'ذخیره', N'از این به بعد، این خصوصیت در فرم کالاهای همان گروه‌ها نمایش داده می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditCategory', 0, NULL, N'Title', N'عنوان گروه', N'نامی که در منو، فیلترهای فروشگاه و مسیر صفحه نمایش داده می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditCategory', 1, NULL, N'Slug', N'اسلاگ', N'بخش انگلیسی آدرس گروه، مثلاً women.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditCategory', 2, NULL, N'ParentId', N'گروه والد', N'برای ساخت زیرگروه، گروه اصلی را انتخاب کنید. برای گروه اصلی «بدون والد» بماند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditCategory', 3, NULL, N'SortOrder', N'ترتیب', N'عدد کمتر یعنی نمایش زودتر در فهرست.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditCategory', 4, NULL, N'IsActive', N'فعال', N'گروه غیرفعال در سایت نمایش داده نمی‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditCategory', 5, N'.admin-main form .btn-store[type=submit]', NULL, N'ذخیره', N'گروه ذخیره می‌شود و به فهرست گروه‌ها برمی‌گردید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditCollection', 0, NULL, N'Title', N'عنوان برچسب', N'مثلاً «ویژه روز دختر». همین عنوان بالای ردیف کالاها در صفحه اول نمایش داده می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditCollection', 1, NULL, N'Description', N'توضیح کوتاه', N'یک جمله که زیر عنوان ردیف در صفحه اول و بالای صفحه برچسب می‌آید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditCollection', 2, NULL, N'SortOrder', N'ترتیب', N'ترتیب نمایش برچسب در فهرست‌ها؛ عدد کمتر زودتر می‌آید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditCollection', 3, NULL, N'showOnHome', N'نمایش در صفحه اول', N'با این تیک یک ردیف از کالاهای برچسب زیر بنر اصلی صفحه اول اضافه می‌شود. جایش را بعداً در «چیدمان صفحات» تغییر دهید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditCollection', 4, N'#pickSearch', NULL, N'جستجوی کالا', N'نام کالا را تایپ کنید تا فهرست پایین فیلتر شود. «فقط انتخاب‌شده‌ها» کالاهای تیک‌خورده را نشان می‌دهد.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditCollection', 5, N'#pickGrid', NULL, N'انتخاب کالاها', N'روی هر کالا کلیک کنید تا به برچسب اضافه شود. تعداد کالاهای انتخاب‌شده کنار عنوان نمایش داده می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditCollection', 6, N'.admin-main form .btn-store[type=submit]', NULL, N'ذخیره برچسب', N'با ذخیره، برچسب روی کالاها ثبت می‌شود و اگر تیک صفحه اول را زده باشید، ردیفش در سایت نمایش داده می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditMenu', 0, NULL, N'Title', N'عنوان', N'متنی که در منو نمایش داده می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditMenu', 1, NULL, N'Url', N'آدرس', N'آدرس صفحه مقصد. برای صفحات خود فروشگاه، آدرس را از نوار مرورگر کپی کنید؛ لینک سایت‌های دیگر هم مجاز است.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditMenu', 2, NULL, N'Location', N'محل نمایش', N'«منوی اصلی» بالای سایت و «فوتر» پایین سایت.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditMenu', 3, NULL, N'ParentId', N'والد', N'برای ساخت زیرمنو، آیتم والد را انتخاب کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditMenu', 4, NULL, N'SortOrder', N'ترتیب و فعال بودن', N'عدد کمتر زودتر نمایش داده می‌شود. آیتم غیرفعال در سایت دیده نمی‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditMenu', 5, N'.admin-main form .btn-store[type=submit]', NULL, N'ذخیره', N'آیتم بلافاصله در منوی سایت نمایش داده می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditPage', 0, NULL, N'Title', N'عنوان صفحه', N'مثلاً «درباره ما». در بالای صفحه و عنوان مرورگر نمایش داده می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditPage', 1, NULL, N'Slug', N'اسلاگ', N'بخش انگلیسی آدرس صفحه، مثلاً about.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditPage', 2, N'.tox-tinymce, #BodyHtml', NULL, N'محتوای صفحه', N'متن، تیتر، لیست، جدول و تصویر اضافه کنید. برای تصویر، آدرسش را از بخش «گالری» کپی کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditPage', 3, NULL, N'IsPublished', N'انتشار', N'تا این تیک زده نشود، صفحه پیش‌نویس می‌ماند و در سایت نمایش داده نمی‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditPage', 4, N'#pageForm .btn-store[type=submit]', NULL, N'ذخیره صفحه', N'بعد از ذخیره، با دکمه «پیش‌نمایش» صفحه را همان‌طور که مشتری می‌بیند ببینید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditProduct', 0, NULL, N'Title', N'عنوان محصول', N'نام کالا همان‌طور که مشتری می‌بیند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditProduct', 1, NULL, N'Slug', N'اسلاگ', N'بخش انگلیسی آدرس صفحه کالا، مثلاً manteau-spring. اگر خالی بماند خودکار ساخته می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditProduct', 2, NULL, N'CategoryId', N'گروه کالا', N'گروه را انتخاب کنید. خصوصیات پایین صفحه بر اساس همین گروه نمایش داده می‌شوند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditProduct', 3, NULL, N'Price', N'قیمت', N'قیمت به تومان. موجودی را هم در کادر کناری وارد کنید؛ با موجودی صفر، کالا ناموجود نمایش داده می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditProduct', 4, NULL, N'ShortDescription', N'توضیح کوتاه', N'یک جمله که زیر عنوان کالا و در نتایج جستجو نمایش داده می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditProduct', 5, NULL, N'Description', N'توضیحات کامل', N'جزئیات کالا که در تب «توضیحات» صفحه محصول می‌آید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditProduct', 6, NULL, N'imageFiles', N'عکس‌های محصول', N'چند عکس را با هم انتخاب کنید. نسخه کوچک و بزرگ خودکار ساخته می‌شود و مشتری می‌تواند در گالری ورق بزند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditProduct', 7, NULL, N'IsActive', N'فعال و ویژه', N'کالای غیرفعال در سایت نمایش داده نمی‌شود. کالای «ویژه» در بخش محصولات ویژه صفحه اول می‌آید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditProduct', 8, NULL, N'CollectionIds', N'برچسب‌های ویژه', N'کالا را به برچسب‌هایی مثل «ویژه روز دختر» اضافه کنید تا در ردیف همان برچسب در صفحه اول نمایش داده شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditProduct', 9, N'#attrs', NULL, N'خصوصیات', N'سایز، رنگ، جنس و دیگر خصوصیات گروه را پر کنید. مشتری می‌تواند در فروشگاه با همین‌ها فیلتر کند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'EditProduct', 10, N'#productForm .btn-store[type=submit]', NULL, N'ذخیره محصول', N'با ذخیره، کالا بلافاصله در سایت نمایش داده می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Gallery', 0, NULL, N'title', N'عنوان و آلبوم', N'یک عنوان و نام آلبوم بنویسید تا تصاویر مرتب بمانند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Gallery', 1, NULL, N'imageFiles', N'انتخاب تصاویر', N'چند تصویر را با هم انتخاب کنید و «آپلود» را بزنید. نسخه کوچک و بزرگ خودکار ساخته می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Gallery', 2, N'.admin-main .input-group', NULL, N'کپی آدرس تصویر', N'دکمه «کپی» آدرس تصویر را کپی می‌کند تا در ویرایشگر صفحات (درج تصویر) استفاده کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Gallery', 3, N'.admin-main .is-delete', NULL, N'حذف تصویر', N'تصویر حذف‌شده در صفحاتی که از آن استفاده کرده‌اند هم دیگر نمایش داده نمی‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Index', 0, N'.admin-side', NULL, N'منوی پنل مدیریت', N'همه بخش‌های فروشگاه از این منو در دسترس است: اطلاعات فروشگاه، محصولات، سفارش‌ها و بقیه. در هر صفحه دکمه «آموزش این صفحه» آموزش همان صفحه را نشان می‌دهد.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Index', 1, N'.ob-checklist', NULL, N'آماده‌سازی فروشگاه برای فروش', N'تا وقتی کاری باقی مانده باشد، این فهرست قدم‌های لازم برای شروع فروش را نشان می‌دهد. روی «انجام بده» بزنید تا مستقیم به همان بخش بروید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Index', 2, N'.admin-main .row.g-3', NULL, N'آمار کلی', N'تعداد محصولات، سفارش‌ها و مشتریان فروشگاه را در یک نگاه ببینید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Index', 3, N'.admin-main .panel-card .table', NULL, N'آخرین سفارش‌ها', N'تازه‌ترین سفارش‌ها با مبلغ و وضعیت اینجا می‌آیند. برای تغییر وضعیت سفارش به منوی «سفارش‌ها» بروید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Index', 4, N'.admin-main a.btn-outline-store[target=_blank]', NULL, N'مشاهده فروشگاه', N'فروشگاه را همان‌طور که مشتری می‌بیند در یک زبانه جدید باز کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Index', 5, N'.admin-side a[href$="/Setup"]', NULL, N'راه‌اندازی سریع', N'اگر تازه شروع کرده‌اید، با راه‌اندازی سریع در ۵ قدم کوتاه فروشگاه را آماده فروش کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Menus', 0, N'.admin-main .btn-store', NULL, N'آیتم جدید', N'یک لینک به منوی اصلی یا فوتر اضافه کنید؛ مثلاً لینک یک گروه کالا یا صفحه «درباره ما».');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Menus', 1, N'.admin-main .panel-card .table', NULL, N'فهرست منوها', N'ستون «محل» نشان می‌دهد آیتم در منوی اصلی است یا فوتر. زیرمنوها با تورفتگی زیر والدشان می‌آیند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Menus', 2, N'.admin-main .table a[href*="EditMenu"]', NULL, N'ویرایش', N'عنوان، آدرس، ترتیب یا والد یک آیتم را تغییر دهید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Orders', 0, N'.admin-main .panel-card .table', NULL, N'فهرست سفارش‌ها', N'شماره سفارش، نام و موبایل مشتری، مبلغ و وضعیت فعلی هر سفارش در این جدول است.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Orders', 1, N'.admin-main .table .is-view', NULL, N'جزئیات و تغییر وضعیت', N'با این آیکون جزئیات سفارش باز می‌شود؛ آنجا وضعیت را تغییر دهید و بعد از ارسال بسته، کد رهگیری مرسوله را ثبت کنید تا مشتری ببیند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Orders', 2, NULL, NULL, N'پرداخت آنلاین', N'اگر درگاه زرین‌پال فعال باشد، سفارش‌ها بعد از پرداخت موفق ثبت می‌شوند. درگاه را از «اطلاعات فروشگاه» تنظیم کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'PageLayout', 0, N'#lsList', NULL, N'بخش‌های صفحه اول', N'هر ردیف یک بخش از صفحه اول سایت است، به همان ترتیبی که مشتری از بالا به پایین می‌بیند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'PageLayout', 1, N'#lsList .ls-actions', NULL, N'جابه‌جا کردن بخش', N'با فلش‌های بالا و پایین بخش را جابه‌جا کنید، یا دستگیره کنار آیکون را بگیرید و بکشید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'PageLayout', 2, N'#lsList .ls-switch', NULL, N'نمایش یا مخفی کردن', N'با این کلید بخش را بدون حذف کردن از سایت پنهان کنید؛ هر وقت خواستید دوباره روشنش کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'PageLayout', 3, N'#lsList [data-edit]', NULL, N'تنظیمات بخش', N'عنوان بخش، کالاهایی که نمایش داده شوند و تعدادشان را از اینجا تغییر دهید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'PageLayout', 4, N'.ls-add', NULL, N'افزودن بخش تازه', N'«ردیف محصولات» کالاهای یک برچسب مثل «ویژه روز دختر»، پرفروش‌ها یا تخفیف‌دارها را نشان می‌دهد. «بنر تبلیغاتی» برای جشنواره‌ها و مناسبت‌هاست.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'PageLayout', 5, N'.ls-options', NULL, N'صفحه محصول', N'محصولات مشابه، نظرات مشتریان، مشخصات فنی و مزایای خرید را در صفحه هر کالا روشن یا خاموش کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'PageLayout', 6, N'.ls-savebar', NULL, N'ذخیره چیدمان', N'تغییرات تا ذخیره نشوند روی سایت اعمال نمی‌شوند. بعد از ذخیره، با «مشاهده صفحه اول» نتیجه را ببینید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Pages', 0, N'.admin-main .btn-store', NULL, N'صفحه جدید', N'یک صفحه بسازید و محتوایش را با ویرایشگر دیداری مثل یک سند ورد طراحی کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Pages', 1, N'.admin-main .panel-card .table', NULL, N'فهرست صفحات', N'صفحه‌های «پیش‌نویس» فقط برای شما قابل دیدن هستند و صفحه‌های «منتشر» در سایت در دسترس‌اند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Pages', 2, N'.admin-main .table a[target=_blank]', NULL, N'مشاهده صفحه', N'صفحه را در سایت ببینید. برای نمایش در منو، آدرسش را در بخش «منوها» اضافه کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Products', 0, N'.admin-side a[href$="/Products"]', NULL, N'منوی محصولات', N'از این منو همیشه به فهرست محصولات برمی‌گردید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Products', 1, N'.admin-main .btn-store', NULL, N'محصول جدید', N'برای اضافه کردن کالا این دکمه را بزنید. عنوان، قیمت، موجودی و عکس‌ها را در صفحه بعد وارد می‌کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Products', 2, N'.admin-main .panel-card .table', NULL, N'فهرست محصولات', N'همه کالاها با عکس، گروه، قیمت و موجودی در این جدول هستند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Products', 3, N'.admin-main .table a[href*="EditProduct"]', NULL, N'ویرایش', N'برای تغییر قیمت، موجودی، عکس‌ها یا برچسب‌های یک کالا روی آیکون مداد بزنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Products', 4, N'.admin-main .table .is-delete', NULL, N'حذف', N'کالا بعد از تأیید حذف می‌شود. اگر فقط می‌خواهید موقتاً نمایش داده نشود، در ویرایش تیک «فعال» را بردارید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Products', 5, N'.admin-side a[href$="/Collections"]', NULL, N'برچسب‌های ویژه', N'برای نمایش گروهی از کالاها در صفحه اول، مثلاً «ویژه روز دختر»، از برچسب‌های ویژه استفاده کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Reviews', 0, N'.admin-main .panel-card .table', NULL, N'فهرست نظرات', N'هر نظر با نام کالا، نویسنده، امتیاز و متن نمایش داده می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Reviews', 1, N'.admin-main .table .is-toggle, .admin-main .table .is-ok', NULL, N'تأیید یا مخفی کردن', N'فقط نظرهای تأییدشده در صفحه محصول نمایش داده می‌شوند. با همین دکمه نظر را مخفی یا دوباره تأیید کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Reviews', 2, N'.admin-main .table .is-delete', NULL, N'حذف نظر', N'نظرهای نامناسب را برای همیشه حذف کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Reviews', 3, NULL, NULL, N'خاموش کردن نظرات', N'اگر نمی‌خواهید مشتری نظر بنویسد، از «چیدمان صفحات» بخش نظرات صفحه محصول را خاموش کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Settings', 0, NULL, N'logoFile', N'لوگو', N'فایل لوگو را انتخاب کنید. برای حذف لوگو، تیک «حذف لوگو» را بزنید تا نام فروشگاه به‌جای آن نمایش داده شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Settings', 1, NULL, N'heroFile', N'تصویر بنر صفحه اول', N'تصویر بزرگ بالای صفحه اول سایت. عکس افقی و باکیفیت بهترین نتیجه را دارد.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Settings', 2, NULL, N'StoreName', N'نام و شعار', N'نام فروشگاه و یک شعار کوتاه که کنار نام نمایش داده می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Settings', 3, NULL, N'About', N'درباره فروشگاه', N'متن معرفی که در صفحه اول و فوتر سایت می‌آید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Settings', 4, NULL, N'Phone', N'اطلاعات تماس', N'تلفن، ایمیل و آدرس در فوتر و صفحه تماس نمایش داده می‌شوند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Settings', 5, NULL, N'HeroTitle', N'متن بنر', N'عنوان و زیرعنوانی که روی تصویر بنر صفحه اول نوشته می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Settings', 6, NULL, N'PrimaryColor', N'رنگ‌های فروشگاه', N'رنگ اصلی دکمه‌ها و رنگ فرعی را انتخاب کنید. با انتخاب قالب، این رنگ‌ها خودکار تنظیم می‌شوند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Settings', 7, N'.tpl-grid', NULL, N'قالب ظاهری', N'روی یک قالب کلیک کنید. با «پیش‌نمایش بزرگ» می‌توانید قبل از انتخاب، فروشگاه خودتان را با آن قالب ببینید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Settings', 8, NULL, N'InstagramUrl', N'شبکه‌های اجتماعی', N'لینک کامل هر شبکه را وارد کنید تا آیکونش در فوتر سایت نمایش داده شود. خالی‌ها نمایش داده نمی‌شوند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Settings', 9, NULL, N'EnamadHtml', N'اینماد', N'کد HTML نماد اعتماد را از پنل enamad.ir کپی کنید و اینجا بگذارید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Settings', 10, NULL, N'customDomain', N'دامنه اختصاصی', N'دامنه را بدون http و www وارد کنید و رکورد A را در پنل دامنه روی آدرس سرور تنظیم کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Settings', 11, NULL, N'ZarinPalMerchantId', N'درگاه پرداخت', N'مرچنت کد زرین‌پال را وارد کنید و «فعال بودن پرداخت» را تیک بزنید. حالت تست فقط برای آزمایش است.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Settings', 12, NULL, N'EnableTorob', N'اتصال به ترب', N'با فعال کردن این گزینه، محصولات شما در ترب نمایش داده می‌شوند. آدرس API پایین همین بخش را در پنل فروشندگان ترب ثبت کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Settings', 13, NULL, N'AdminUsername', N'مدیر فروشگاه', N'نام کاربری ورود به همین پنل. اگر کادر رمز جدید را خالی بگذارید، رمز فعلی تغییر نمی‌کند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Settings', 14, N'.admin-main form .btn-store[type=submit]', NULL, N'ذخیره تنظیمات', N'بعد از هر تغییر این دکمه را بزنید تا روی سایت اعمال شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Setup', 0, N'.ob-stepper', NULL, N'قدم‌های راه‌اندازی', N'نام و لوگو، ظاهر فروشگاه، اولین محصول، درگاه پرداخت و آدرس سایت. با کلیک روی هر قدم مستقیم به آن می‌روید؛ قدم‌های انجام‌شده تیک می‌خورند.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Setup', 1, NULL, N'storeName', N'نام فروشگاه', N'نامی که بالای سایت، در فوتر و عنوان صفحات نمایش داده می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Setup', 2, NULL, N'logoFile', N'لوگو', N'بهتر است PNG با پس‌زمینه شفاف باشد. اگر لوگو ندارید، نام فروشگاه به‌جای آن نمایش داده می‌شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Setup', 3, N'.tpl-grid', NULL, N'انتخاب قالب', N'روی یک قالب کلیک کنید تا رنگ‌ها خودکار تنظیم شوند. تصویر هر قالب، فروشگاه خودتان با همان محصولات است.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Setup', 4, NULL, N'title', N'اولین محصول', N'فقط عنوان، قیمت و یک عکس کافی است؛ جزئیات بیشتر را بعداً از بخش «محصولات» اضافه کنید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Setup', 5, NULL, N'merchantId', N'درگاه پرداخت', N'مرچنت کد زرین‌پال را اینجا وارد کنید تا پول هر سفارش مستقیم به حساب خودتان واریز شود.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Setup', 6, NULL, N'customDomain', N'دامنه اختصاصی', N'اگر دامنه دارید وارد کنید و رکوردهای DNS نوشته‌شده در همین صفحه را در پنل دامنه بسازید.');
INSERT INTO [dbo].[TutorialSteps] ([Page], [Position], [Target], [Field], [Title], [Text]) VALUES (N'Setup', 7, N'.ob-actions .btn-store', NULL, N'ذخیره و ادامه', N'اطلاعات ذخیره می‌شود و به قدم بعد می‌روید. در بعضی قدم‌ها دکمه «رد شدن» هم هست.');
